/**
 * Carga el lote de 8 muestras industriales oficiales al Banco IA.
 * @param {boolean} forceReload
 * @returns {Promise<number>}
 */
export async function loadFactorySeedSamplesToDB(forceReload = false) {
    try {
        const { initDatasetDB, getAllSamples } = await import('./datasetManager.js');
        const db = await initDatasetDB();
        if (!db) return 0;

        const current = await getAllSamples();
        // Si se fuerza o si tiene muestras antiguas (como las cenitales de MVTec), purgar y recargar
        if (current.length > 0 && !forceReload && !current.some(s => s.id && s.id.includes('mvtec'))) {
            return 0;
        }

        const tx = db.transaction('samples', 'readwrite');
        const store = tx.objectStore('samples');

        // Purgar muestras antiguas para limpiar la galería
        await new Promise((resolve) => {
            const clearReq = store.clear();
            clearReq.onsuccess = () => resolve();
            clearReq.onerror = () => resolve();
        });

        const tx2 = db.transaction('samples', 'readwrite');
        const store2 = tx2.objectStore('samples');
        for (const sample of FACTORY_SEED_SAMPLES) {
            store2.put(sample);
        }

        return new Promise((resolve) => {
            tx2.oncomplete = () => {
                console.log(`[SeedDataset] ${FACTORY_SEED_SAMPLES.length} muestras fotográficas de perfil cargadas en Banco IA.`);
                resolve(FACTORY_SEED_SAMPLES.length);
            };
            tx2.onerror = () => resolve(0);
        });
    } catch (err) {
        console.error('[SeedDataset] Error cargando muestras semilla:', err);
        return 0;
    }
}
